.poker-entry-note { margin:16px 0 0; font:.9rem/1.6 var(--sans); color:var(--ink-soft); }
.poker-entry-search { margin:22px 0 0; font:1rem/1.65 var(--serif); }
.poker-foundations-card { border:1px solid var(--basalt); border-top:4px solid var(--red); padding:clamp(20px,4vw,40px); background:var(--paper-light); min-width:0; }
.poker-foundations-card .section-title { margin:10px 0 18px; }
.poker-course-facts { display:grid; grid-template-columns:repeat(3,minmax(0,1fr)); gap:18px; padding:20px 0; margin:24px 0; border-block:1px solid var(--ink-soft); font:.9rem/1.5 var(--sans); }
.poker-course-facts dt { font-weight:700; margin:0 0 6px; }
.poker-course-facts dd { margin:0; }
