.poker-foundations-syllabus li { min-width:0; padding-inline-start:4px; font:.95rem/1.5 var(--sans); }
.poker-foundations-syllabus li::marker { color:var(--red); font-weight:700; }
.poker-foundations-syllabus a { display:inline-flex; align-items:center; min-height:44px; font-weight:700; text-underline-offset:.2em; }
.poker-foundations-syllabus p { margin:4px 0 0; font:.95rem/1.6 var(--serif); }
